def shapes(grid):
    # find connected non-zero components by color, return bounding boxes ordered by left col
    from collections import defaultdict
    cells=defaultdict(list)
    for i,row in enumerate(grid):
        for j,v in enumerate(row):
            if v: cells[v].append((i,j))
    out=[]
    for v,pts in cells.items():
        rs=[p[0] for p in pts]; cs=[p[1] for p in pts]
        out.append((min(cs), min(rs), max(rs), v))
    out.sort()
    res=[]
    for _,r0,r1,v in out:
        res.append([[v if grid[i][j]==v else 0 for j in range(r0,r1+1)] for i in range(r0,r1+1)])  # fix below
    return res
